import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show TargetPlatform, defaultTargetPlatform, kIsWeb;

class DefaultFirebaseOptions {
  const DefaultFirebaseOptions._();

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      return web;
    }

    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;

      case TargetPlatform.iOS:
      case TargetPlatform.macOS:
        throw UnsupportedError(
          'Firebase is not configured for Apple platforms yet. Run '
          '`flutterfire configure --project=finora-transaction-manager` and '
          'select iOS and macOS. It will also place GoogleService-Info.plist.',
        );

      case TargetPlatform.windows:
      case TargetPlatform.linux:
      case TargetPlatform.fuchsia:
        throw UnsupportedError(
          'Firebase has no SDK for ${defaultTargetPlatform.name}. Use Android, '
          'iOS or the web build.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyAm9IZ-dbqN4uya82nKaTZQ0uddLpSFfn4',
    appId: '1:905382059562:android:7ededca9185fbde5832d53',
    messagingSenderId: '905382059562',
