    storageBucket: 'finora-transaction-manager.firebasestorage.app',
  );

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: 'AIzaSyD8AH-0KbA9wehtvE6DiVszuKWIH4_nTHA',
